return $input.all().map((item) => {
  const event = item.json;
  const consent = event.consent || {};
  const suppressed = Boolean(event.suppressed || event.payload?.suppressed);
  return { json: { ...event, permissions: { reply: !suppressed && consent.replyRequested === true, operational: !suppressed && (consent.registration === true || consent.replyRequested === true), marketing: !suppressed && consent.marketing === true, suppressed } } };
});
